use std::{io::{BufRead,BufReader,Write},os::unix::net::UnixListener,path::PathBuf,fs};
use apassy::{browser::{site::{Page,Website},wire::{Request,Command,Response,Data,VaultState,LoginRow}},desktop::{owner_store::{OwnerSession,SecretForm},model::{ItemDraft,DetailDraft}},contracts::CredentialKind};
fn list(session:&OwnerSession,url:&str,prefix:Option<&str>)->Response{let p=match Page::parse(url){Ok(p)=>p,Err(e)=>return Response::error("unsupported_page",e.message())};let r=match prefix{Some(q)=>session.suggestions_for_page(&p,q),None=>session.logins_for_page(&p)};match r{Ok(rows)=>Response::ok("Scratch metadata only",Data::Logins{origin:p.origin(),host:p.host(),logins:rows.into_iter().map(|x|LoginRow{item:x.id,title:x.title,username:x.username,has_totp:x.has_totp}).collect()}),Err(e)=>Response::error(e.code,e.message)}}
fn main(){let root=PathBuf::from(std::env::args().nth(1).unwrap());let mut session=OwnerSession::new();session.create_file(&root.join("scratch-vault.apassy"),"audit-only-scratch-passphrase-2026").unwrap();session.unlock("audit-only-scratch-passphrase-2026").unwrap();
let seeds=[("Example base","example.com"),("GitHub","github.com"),("GitLab","gitlab.com"),("Example subdomain","app.example.com"),("Local 8080","http://localhost:8080"),("No Website",""),("Google","google.com"),("Microsoft","microsoftonline.com"),("X","x.com"),("Vercel","vercel.com"),("Fixture",&format!("http://localhost:{}",std::env::var("FIXTURE_PORT").unwrap())),("Fixture IP",&format!("http://127.0.0.1:{}",std::env::var("FIXTURE_PORT").unwrap())),("WWW","www.example.org"),("Unicode legacy",""),("Punycode","xn--mnchen-3ya.de"),("Multiple URL fields","multi.example"),("Multiple URLs one field","")];
for (name,site) in seeds {let mut draft=ItemDraft{name:name.to_owned(),kind:CredentialKind::Login,username:"audit@example.test".into(),website:site.into(),..Default::default()};if name=="Multiple URL fields"{draft.details.push(DetailDraft{label:"Website 2".into(),value:"second.example".into(),..Default::default()});}if name=="Unicode legacy"{draft.details.push(DetailDraft{label:"Website imported".into(),value:"münchen.de".into(),..Default::default()});}if name=="Multiple URLs one field"{draft.details.push(DetailDraft{label:"Website list".into(),value:"https://first.example https://second.example".into(),..Default::default()});}let mut secrets=SecretForm::default();secrets.password="synthetic-only-never-requested".into();session.add(&draft,&secrets).unwrap();}
let pairs=[("example.com","https://app.example.com"),("app.example.com","https://example.com"),("app.example.com","https://auth.example.com"),("www.example.com","https://example.com"),("www.example.com","https://app.example.com"),("http://example.com","https://example.com"),("http://localhost:8080","http://localhost:8080"),("http://localhost:8080","http://localhost:8081"),("münchen.de","https://xn--mnchen-3ya.de"),("xn--mnchen-3ya.de","https://xn--mnchen-3ya.de"),("co.uk","https://unrelated.co.uk"),("github.io","https://unrelated.github.io"),("https://first.example https://second.example","https://second.example")];let matches:Vec<_>=pairs.iter().map(|(s,u)|serde_json::json!({"website":s,"page":u,"parsed":Website::parse(s).is_some(),"matches":Website::parse(s).is_some_and(|s|s.matches(&Page::parse(u).unwrap()))})).collect();fs::write(root.join("matching.json"),serde_json::to_vec_pretty(&matches).unwrap()).unwrap();
let l=UnixListener::bind(root.join("b.sock")).unwrap();println!("scratch backend ready");for st in l.incoming(){let Ok(mut st)=st else{continue};let mut line=String::new();if BufReader::new(&st).read_line(&mut line).is_err(){continue};let mut log=fs::OpenOptions::new().append(true).create(true).open(root.join("real-requests.jsonl")).unwrap();writeln!(log,"{}",line.trim()).unwrap();let answer=match Request::parse(line.as_bytes()){Ok(Command::Status)=>Response::ok("Scratch vault",Data::Status{vault:VaultState::Unlocked,version:"0.5.7-audit-adapter".into()}),Ok(Command::Logins{url})=>list(&session,&url,None),Ok(Command::Suggestions{url,username})=>list(&session,&url,Some(&username)),Ok(_)=>Response::error("refused","Audit: only metadata requests are allowed."),Err(e)=>Response::error(e.code,e.message)};let _=writeln!(st,"{}",serde_json::to_string(&answer).unwrap());}}
